                    {
                        return false;
                    }
                    String8 symbol_name = string_format(builder->arena, S8(".L.{S8}.{S8}.{u64}"), builder->function->name, name.spelling, name.location.offset);
                    IrSourceRange local_source = c_ir_source_range(name.location, name.spelling.length);
